"""Read-only live evidence checks. Fixtures are separately labelled unit tests."""import asyncioimport jsonimport sysfrom datetime import datetime, timedelta, timezoneimport httpxfrom local_support import ROOTsys.path.insert(0, str(ROOT / "apps/ai-engine"))from evidence.loki import search_loki  # noqa: E402from evidence.models import Window  # noqa: E402from evidence.prometheus import query_prometheus  # noqa: E402async def main():    async with httpx.AsyncClient() as client:        response = await client.get("http://127.0.0.1:3001/health")        response.raise_for_status()    await asyncio.sleep(4)    end = datetime.now(timezone.utc)    window = Window(        service="checkout-service", start=end - timedelta(minutes=5), end=end    )    async with httpx.AsyncClient() as client:        value = await query_prometheus(client, "http://127.0.0.1:9090", window)        assert value.status in {"OK", "PARTIAL"}, value.status        assert value.data["series"]["request_rate"], "No real request-rate samples"        missing = await query_prometheus(client, "http://127.0.0.1:1", window)        assert missing.status == "UNAVAILABLE"        logs = await search_loki(client, "http://127.0.0.1:3100", window)        assert logs.status in {"OK", "PARTIAL"}, logs.status        assert logs.data["retrieved_count"] > 0        assert (            await search_loki(client, "http://127.0.0.1:1", window)        ).status == "UNAVAILABLE"    report = {        "at": end.isoformat(),        "prometheus": value.model_dump(mode="json"),        "negative": missing.status,        "loki": logs.model_dump(mode="json"),        "data_kind": "live local collectors",    }    output = ROOT / ".artifacts/p5-verification.json"    output.write_text(json.dumps(report, indent=2), encoding="utf-8")    print(        "P5.1–P5.2 live metrics/logs and unreachable-source checks passed; report:",        output,    )if __name__ == "__main__":    asyncio.run(main())